    "title": "Here and There — “Here is/are…, There is/are…”", "skillSteps": {"Here or There": "pattern", "Three forms": "compare", "Word order": "p2", "Negative sentences": "p6", "Questions": "p4", "Short answers": "p11", "Fixing mistakes": "p10", "Translation": "p3", "Writing your own sentences": "wr", "Real-life use": "convo"}, "tagWhy": {"Affirmative": HT, "Negative": NEG4, "Question": QW4}, "write": {"mixed": true, "subs": ["here", "there"], "qSubs": ["there"], "contr": ["here", "there"], "msg": {"aff": {"en": "Start with “Here is / are” or “There is / are” and add a noun. Example: Here is my pen.", "hi": "“Here is / are” या “There is / are” से शुरू कीजिए और संज्ञा जोड़िए। जैसे: Here is my pen."}, "neg": {"en": "Use “There is not” or “There are not” and a noun. Example: There is not a bus.", "hi": "“There is not” या “There are not” लगाइए और संज्ञा जोड़िए। जैसे: There is not a bus."}, "q": {"en": "Start with “Is there” or “Are there” and add a noun. Example: Are there two chairs?", "hi": "“Is there” या “Are there” से शुरू कीजिए और संज्ञा जोड़िए। जैसे: Are there two chairs?"}}}, 
